import { useCallback, useEffect, useMemo, useState } from "react";
import { useAuth } from "../context/useAuth";
import axios from "axios";
import "../App.css";

const EXPENSE_API = "http://localhost:5000/api/expenses";
const BUDGET_API = "http://localhost:5000/api/budgets";

const authConfig = (token) => ({
  headers: {
    Authorization: `Bearer ${token}`,
  },
});

const categories = [
  "Food",
  "Transport",
  "Shopping",
  "Entertainment",
  "Bills",
  "Healthcare",
  "Education",
  "Other",
];

const paymentMethods = [
  "Cash",
  "UPI",
  "Card",
  "Bank Transfer",
];

const initialExpenseForm = {
  amount: "",
  category: "",
  date: new Date().toISOString().split("T")[0],
  paymentMethod: "",
  description: "",
};

const initialBudgetForm = {
  amount: "",
  category: "",
  month: new Date().getMonth() + 1,
  year: new Date().getFullYear(),
};

function ExpenseTracker(){
  // =========================
  // GENERAL
  // =========================
  const { user, token, logout } = useAuth();
  const [activePage, setActivePage] = useState("dashboard");
  const [message, setMessage] = useState("");

  // =========================
  // EXPENSES
  // =========================

  const [expenses, setExpenses] = useState([]);
  const [loadingExpenses, setLoadingExpenses] = useState(true);
  const [expenseModal, setExpenseModal] = useState(false);
  const [expenseForm, setExpenseForm] = useState(initialExpenseForm);
  const [editingExpenseId, setEditingExpenseId] = useState(null);
  const [expenseSearch, setExpenseSearch] = useState("");

  // =========================
  // BUDGETS
  // =========================

  const [budgets, setBudgets] = useState([]);
  const [loadingBudgets, setLoadingBudgets] = useState(true);
  const [budgetModal, setBudgetModal] = useState(false);
  const [budgetForm, setBudgetForm] = useState(initialBudgetForm);
  const [editingBudgetId, setEditingBudgetId] = useState(null);

  // =========================
  // SUMMARY
  // =========================

  const [summaryMonth, setSummaryMonth] = useState(
    new Date().getMonth() + 1
  );

  const [summaryYear, setSummaryYear] = useState(
    new Date().getFullYear()
  );

  const [summary, setSummary] = useState(null);
  const [summaryLoading, setSummaryLoading] = useState(false);

  const showMessage = useCallback((text) => {
    setMessage(text);
    setTimeout(() => setMessage(""), 3000);
  }, []);

  // =========================
  // FETCH EXPENSES
  // =========================

  const fetchExpenses = useCallback(async () => {
    if (!token) return;
    try {
      const response = await axios.get(EXPENSE_API, authConfig(token));
      setExpenses(response.data);
    } catch (error) {
      console.error(error);
      showMessage("Failed to load expenses.");
    } finally {
      setLoadingExpenses(false);
    }
  }, [showMessage, token]);

  // =========================
  // FETCH BUDGETS
  // =========================

  const fetchBudgets = useCallback(async () => {
    if (!token) return;
    try {
      const response = await axios.get(BUDGET_API, authConfig(token));
      setBudgets(response.data);
    } catch (error) {
      console.error(error);
      showMessage("Failed to load budgets.");
    } finally {
      setLoadingBudgets(false);
    }
  }, [showMessage, token]);

  // =========================
  // FETCH SUMMARY
  // =========================

  const fetchBudgetSummary = useCallback(async () => {
    if (!token) return;
    try {
      const response = await axios.get(
        `${BUDGET_API}/summary/${summaryMonth}/${summaryYear}`,
        authConfig(token)
      );

      setSummary(response.data);
    } catch (error) {
      console.error(error);
      showMessage("Failed to load budget summary.");
    } finally {
      setSummaryLoading(false);
    }
  }, [showMessage, summaryMonth, summaryYear, token]);

  useEffect(() => {
    queueMicrotask(() => {
      void fetchExpenses();
      void fetchBudgets();
    });
  }, [fetchBudgets, fetchExpenses]);

  useEffect(() => {
    queueMicrotask(() => { void fetchBudgetSummary(); });
  }, [fetchBudgetSummary]);

  // =========================
  // MESSAGE
  // =========================

  // =========================
  // EXPENSE FORM
  // =========================

  const handleExpenseChange = (e) => {
    const { name, value } = e.target;

    setExpenseForm((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const openAddExpense = () => {
    setEditingExpenseId(null);
    setExpenseForm(initialExpenseForm);
    setExpenseModal(true);
  };

  const openEditExpense = (expense) => {
    setEditingExpenseId(expense._id);

    setExpenseForm({
      amount: String(expense.amount),
      category: expense.category,
      date: new Date(expense.date).toISOString().split("T")[0],
      paymentMethod: expense.paymentMethod,
      description: expense.description || "",
    });

    setExpenseModal(true);
  };

  const closeExpenseModal = () => {
    setExpenseModal(false);
    setEditingExpenseId(null);
    setExpenseForm(initialExpenseForm);
  };

  const handleExpenseSubmit = async (e) => {
    e.preventDefault();

    try {
      const data = {
        ...expenseForm,
        amount: Number(expenseForm.amount),
      };

      if (editingExpenseId) {
        await axios.put(
          `${EXPENSE_API}/${editingExpenseId}`,
          data,
          authConfig(token)
        );

        showMessage("Expense updated successfully.");
      } else {
        await axios.post(EXPENSE_API, data, authConfig(token));

        showMessage("Expense added successfully.");
      }

      closeExpenseModal();

      await fetchExpenses();
      await fetchBudgetSummary();
    } catch (error) {
      console.error(error);

      showMessage(
        error.response?.data?.message ||
          "Failed to save expense."
      );
    }
  };

  const handleDeleteExpense = async (id) => {
    const confirmed = window.confirm(
      "Are you sure you want to delete this expense?"
    );

    if (!confirmed) return;

    try {
      await axios.delete(`${EXPENSE_API}/${id}`, authConfig(token));

      showMessage("Expense deleted successfully.");

      await fetchExpenses();
      await fetchBudgetSummary();
    } catch (error) {
      console.error(error);

      showMessage("Failed to delete expense.");
    }
  };

  // =========================
  // BUDGET FORM
  // =========================

  const handleBudgetChange = (e) => {
    const { name, value } = e.target;

    setBudgetForm((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const openAddBudget = () => {
    setEditingBudgetId(null);

    setBudgetForm({
      ...initialBudgetForm,
      month: summaryMonth,
      year: summaryYear,
    });

    setBudgetModal(true);
  };

  const openEditBudget = (budget) => {
    setEditingBudgetId(budget._id);

    setBudgetForm({
      amount: String(budget.amount),
      category: budget.category,
      month: budget.month,
      year: budget.year,
    });

    setBudgetModal(true);
  };

  const closeBudgetModal = () => {
    setBudgetModal(false);
    setEditingBudgetId(null);
    setBudgetForm(initialBudgetForm);
  };

  const handleBudgetSubmit = async (e) => {
    e.preventDefault();

    try {
      const data = {
        ...budgetForm,
        amount: Number(budgetForm.amount),
        month: Number(budgetForm.month),
        year: Number(budgetForm.year),
      };

      if (editingBudgetId) {
        await axios.put(
          `${BUDGET_API}/${editingBudgetId}`,
          data,
          authConfig(token)
        );

        showMessage("Budget updated successfully.");
      } else {
        await axios.post(BUDGET_API, data, authConfig(token));

        showMessage("Budget added successfully.");
      }

      closeBudgetModal();

      await fetchBudgets();
      await fetchBudgetSummary();
    } catch (error) {
      console.error(error);

      showMessage(
        error.response?.data?.message ||
          "Failed to save budget."
      );
    }
  };

  const handleDeleteBudget = async (id) => {
    const confirmed = window.confirm(
      "Are you sure you want to delete this budget?"
    );

    if (!confirmed) return;

    try {
      await axios.delete(`${BUDGET_API}/${id}`, authConfig(token));

      showMessage("Budget deleted successfully.");

      await fetchBudgets();
      await fetchBudgetSummary();
