const getBudgetSummary = async (req, res) => {
    try {
        const { month, year } = req.params;

        const selectedMonth = Number(month);
        const selectedYear = Number(year);

        // Get ONLY logged-in user's budgets
        const budgets = await Budget.find({
            user: req.userId,
            month: selectedMonth,
            year: selectedYear,
        });

        // Create date range
        const startDate = new Date(
            selectedYear,
            selectedMonth - 1,
            1
        );

        const endDate = new Date(
            selectedYear,
            selectedMonth,
            1
        );

        // Get ONLY logged-in user's expenses
        const expenses = await Expense.find({
            user: req.userId,
            date: {
                $gte: startDate,
                $lt: endDate,
            },
        });

        // Calculate total spending
        const totalSpent = expenses.reduce(
            (total, expense) =>
                total + expense.amount,
            0
        );

        // Find overall budget
        const overallBudget = budgets.find(
            (budget) =>
                budget.category === "Overall"
        );

        const overallBudgetAmount =
            overallBudget
                ? overallBudget.amount
                : 0;

        // Calculate category spending
        const categorySpending = {};

        expenses.forEach((expense) => {
            if (
                !categorySpending[
                    expense.category
                ]
            ) {
                categorySpending[
                    expense.category
                ] = 0;
            }

            categorySpending[
                expense.category
            ] += expense.amount;
        });

        // Create category summary
        const categories = budgets
            .filter(
                (budget) =>
                    budget.category !== "Overall"
            )
            .map((budget) => {
                const spent =
                    categorySpending[
                        budget.category
                    ] || 0;

                return {
                    category:
                        budget.category,

                    budget:
                        budget.amount,

                    spent,

                    remaining:
                        budget.amount - spent,
                };
            });

        res.status(200).json({
            month: selectedMonth,
            year: selectedYear,

            overall: {
                budget:
                    overallBudgetAmount,

                spent:
                    totalSpent,

                remaining:
                    overallBudgetAmount -
                    totalSpent,
            },

            categories,
        });

    } catch (error) {
        res.status(500).json({
            message:
                "Failed to generate budget summary",

            error: error.message,
        });
    }
};


